def _flatten_fields(self, field_types: dict[str, typing.Any]) -> dict[str, typing.Any]:
    result = {}
    occupied: dict[str, str] = {}
    config = self.get_config()
    for fname, ftype in field_types.items():
        metadata = self.metadatas.get(fname, {})
        if not metadata.get("flatten"):
            keys = {fname}
            alias = self.__get_field_alias(fname, ftype, metadata, config)
            if alias:
                keys.add(alias)
            for key in keys:
                if key in occupied and occupied[key] != fname:
                    raise ValueError(f"Flattened field key collision: {key}")
                occupied[key] = fname
            continue
        typ = self.get_real_type(fname, ftype)
        while is_annotated(typ):
            typ = get_args(typ)[0]
        optional = is_optional(typ)
        if optional:
            typ = next(arg for arg in get_args(typ) if arg is not NoneType)
            while is_annotated(typ):
                typ = get_args(typ)[0]
        origin = typing.get_origin(typ) or typ
        if not isinstance(origin, type) or not is_dataclass(origin):
            raise ValueError(f"Flattened field {fname} must be a dataclass")
        prefix = metadata.get("flatten_prefix", False)
        rename = metadata.get("flatten_rename")
        if not isinstance(prefix, (str, bool)):
            raise ValueError(f"Invalid flatten prefix for {fname}")
        if prefix and rename is not None:
            raise ValueError("flatten_prefix and flatten_rename are mutually exclusive")
        if rename is not None and (not isinstance(rename, dict) or any(not isinstance(k, str) or not isinstance(v, str) for k, v in rename.items())):
            raise ValueError(f"Invalid flatten rename for {fname}")
        rename = rename or {}
        child = CodeBuilder(origin, get_args(typ), format_name=self.format_name)
        child.reset()
        child_types = child.get_field_types(include_extras=True)
        child_flat = child._flatten_fields(child_types)
        names = set(child_types)
        if set(rename) - names:
            raise ValueError(f"Invalid flatten rename keys for {fname}")
        prefix = fname + "_" if prefix is True else prefix or ""
        mapping = {}
        for name, child_type in child_types.items():
            if name in child_flat:
                child_keys = child_flat[name][0].keys()
            else:
                child_metadata = child.metadatas.get(name, {})
                alias = child.__get_field_alias(name, child_type, child_metadata, child.get_config())
                child_keys = {name, alias} if alias else {name}
            for key in child_keys:
                outer = rename.get(name, key) if name in rename else prefix + key
                if outer in occupied and occupied[outer] != (fname, name):
                    raise ValueError(f"Flattened field key collision: {outer}")
                occupied[outer] = (fname, name)
                mapping[key] = outer
        if len(set(rename.values())) != len(rename):
            raise ValueError(f"Duplicate flatten rename values for {fname}")
        result[fname] = (mapping, optional)
    return result

